USE [golden_db];
SET XACT_ABORT ON;
SET LOCK_TIMEOUT 30000;
BEGIN TRY
BEGIN TRANSACTION;
ALTER TABLE [dbo].[child] DROP CONSTRAINT [FK_child_parent];
ALTER TABLE [dbo].[child] DROP CONSTRAINT [CK_child_code];
ALTER TABLE [dbo].[parent] DROP CONSTRAINT [UQ_parent_code];
ALTER TABLE [dbo].[child] ALTER COLUMN [parent_code] varchar(10) COLLATE Latin1_General_100_CS_AS NULL;
ALTER TABLE [dbo].[parent] ALTER COLUMN [code] varchar(10) COLLATE Latin1_General_100_CS_AS NOT NULL;
ALTER TABLE [dbo].[child] WITH NOCHECK ADD CONSTRAINT [CK_child_code] CHECK NOT FOR REPLICATION ([parent_code]<>'');
ALTER TABLE [dbo].[child] NOCHECK CONSTRAINT [CK_child_code];
ALTER TABLE [dbo].[parent] ADD CONSTRAINT [UQ_parent_code] UNIQUE NONCLUSTERED ([code] ASC) WITH (PAD_INDEX = OFF, IGNORE_DUP_KEY = OFF, STATISTICS_NORECOMPUTE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, DATA_COMPRESSION = NONE) ON [PRIMARY];
ALTER TABLE [dbo].[child] WITH NOCHECK ADD CONSTRAINT [FK_child_parent] FOREIGN KEY ([parent_code]) REFERENCES [dbo].[parent] ([code]) ON DELETE SET NULL ON UPDATE NO ACTION NOT FOR REPLICATION;
ALTER TABLE [dbo].[child] NOCHECK CONSTRAINT [FK_child_parent];
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
THROW;
END CATCH;
